// Rebuilds docs/design/kit/ from the component board's own code, so the prototypes beside it are drawn with the shipped parts.
// Run after `pnpm build` (it reads the built design-system, plugin-sdk and workbench):
//   node docs/design/kit/build.mjs
// kit.css: VISUAL_FOUNDATION_STYLES (tokens, coss controls, mw-* primitives, arrival parts, toast, state ring) + CRAFT_FINISH_STYLES
//   (motion: the four entrances and the landed wash; touch targets; the craft base) + the page parts a page also places: the diff
//   view, the process fold (generated by plugin-sdk's processFold for the .pf-* selectors), disclosure, interaction cards, input
//   receipts, media zoom, copy feedback, overflow fade and tabular numbers + the palette hues (--hue-*) and tone aliases for both
//   resolved themes.
// settings.css: the workbench's settings-page stylesheet (renderMolisWorkSettingsStylesheet), for prototypes on the settings page.
// kit.js: the theme bootstrap, the real renderers as window.mwKit, the icon sprite, and the client scripts as strings
//   (window.mwKitClient: visual foundation; window.mwKitClients: craft finish, media zoom, drop zone, copy feedback, overflow fade).
import { build } from "esbuild";
import { writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, "../../..");
const ds = await import(join(root, "packages/design-system/dist/index.js"));
const { renderMolisWorkSettingsStylesheet } = await import(join(root, "apps/workbench/dist/page-assets.js"));
const { processFold } = await import(join(root, "packages/plugin-sdk/dist/ui/process-fold.js"));

const css = [
  ds.VISUAL_FOUNDATION_STYLES, ds.CRAFT_FINISH_STYLES, ds.DIFF_VIEW_STYLES, ds.DISCLOSURE_STYLES, ds.INTERACTION_STYLES, ds.INPUT_RECEIPTS_STYLES,
  ds.MEDIA_ZOOM_STYLES, ds.COPY_FEEDBACK_STYLES, ds.OVERFLOW_FADE_STYLES, ds.NUMBER_STYLES,
  processFold("", { group: ".pf-group", groupBody: ".pf-group__body", step: ".pf-step", stepBody: ".pf-step__body" }),
  // The palette hues (--hue-*) and the tone aliases built on them, for both resolved themes.
  `html{${ds.renderPaletteTokens("light")}} html[data-resolved-theme="dark"]{${ds.renderPaletteTokens("dark")}}`,
].join("\n");
writeFileSync(join(here, "kit.css"), `/* Generated by docs/design/kit/build.mjs from packages/design-system and plugin-sdk. Do not edit. */\n${css}`);

const sdk = (p) => JSON.stringify(join(root, "packages/plugin-sdk/dist", p));
const dsp = (p) => JSON.stringify(join(root, "packages/design-system/dist", p));
const entry = `
import { renderButton, renderStatusMark, renderBadge, renderAlert, renderStateRing, icon, escapeHtml } from ${sdk("ui.js")};
import { renderDiff, compareChange, diffViewText } from ${sdk("diff-view.js")};
import { renderMenu, renderMenuItem, renderMenuGroup, renderPopover, renderTooltip } from ${dsp("primitives/overlay.js")};
import { renderToggleGroup, renderTabs } from ${dsp("primitives/navigation.js")};
import { renderFileKind, renderFileRow, renderFileGroup, renderBarStatus, renderSteps } from ${dsp("primitives/arrival.js")};
window.mwKit = { renderButton, renderStatusMark, renderBadge, renderAlert, renderStateRing, icon, escapeHtml, renderDiff, compareChange, diffViewText,
  renderMenu, renderMenuItem, renderMenuGroup, renderPopover, renderTooltip, renderToggleGroup, renderTabs, renderSteps,
  renderFileKind, renderFileRow, renderFileGroup, renderBarStatus };
`;
const out = await build({ stdin: { contents: entry, resolveDir: root, loader: "js" }, bundle: true, write: false, format: "iife", platform: "browser", minify: true, logLevel: "silent" });
const renderers = out.outputFiles[0].text;
const clients = { craftFinish: ds.CRAFT_FINISH_CLIENT_SCRIPT, mediaZoom: ds.MEDIA_ZOOM_CLIENT_SCRIPT, dropZone: ds.DROP_ZONE_CLIENT_SCRIPT, copy: ds.COPY_FEEDBACK_CLIENT_SCRIPT, overflowFade: ds.OVERFLOW_FADE_CLIENT_SCRIPT };
writeFileSync(join(here, "kit.js"), `/* Generated by docs/design/kit/build.mjs from packages/design-system and packages/plugin-sdk. Do not edit. */
${ds.THEME_BOOTSTRAP_SCRIPT}
${renderers}
window.mwKitSprite = ${JSON.stringify(ds.renderIconSprite())};
window.mwKitClient = ${JSON.stringify(ds.VISUAL_FOUNDATION_CLIENT_SCRIPT)};
window.mwKitClients = ${JSON.stringify(clients)};
`);
// The settings page's own stylesheet (the workbench's), for prototypes drawn on the settings page. Its own file: it is the
// whole settings page, so a prototype elsewhere does not load it.
const settings = renderMolisWorkSettingsStylesheet();
writeFileSync(join(here, "settings.css"), `/* Generated by docs/design/kit/build.mjs from apps/workbench renderMolisWorkSettingsStylesheet(). Do not edit. */\n${settings}`);
console.log("settings.css", settings.length);
console.log("kit.css", css.length, "kit.js", renderers.length);
